    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    ""
  )
  ham <- lapply(bloklar, function(blok) {
    bas <- seq.int(1L, nchar(blok), by = 2L)
    as.raw(strtoi(substring(blok, bas, bas + 1L), base = 16L))
  })
  writeBin(do.call(c, ham), arsiv)
  utils::unzip(arsiv, exdir = proje)
  rm(bloklar, ham)
  invisible(gc())
  komut <- sprintf("setwd(%s); source('Analiz.R')", encodeString(normalizePath(proje), quote='"'))
  rstudioapi::restartSession(command=komut, clean=TRUE)
})
